SELECT CASE WHEN d.budget >= 4173000 THEN 'high' WHEN d.budget >= 1973000 THEN 'mid' ELSE 'low' END AS budget_bucket, MAX(e.salary) - MIN(e.salary) AS salary_range, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(e.job_title))) AS job_title_values FROM employees e RIGHT JOIN departments d ON e.dept_id = d.id GROUP BY CASE WHEN d.budget >= 4173000 THEN 'high' WHEN d.budget >= 1973000 THEN 'mid' ELSE 'low' END ORDER BY budget_bucket LIMIT 5;
